<span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">for</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;"> _, entry </span><span style="--shiki-light:#A0111F;--shiki-dark:#89DDFF;">in</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> ipairs</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(entries) </span><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">do</span></span>
